/**
 * Archives several issues at once. Unknown, foreign and already-archived ids
 * are skipped untouched; every other issue must pass the single-archive
 * permission check before anything is archived or published.
 */
export async function bulkArchiveIssues(
  actor: Actor,
  input: BulkArchiveIssuesInput,
): Promise<{ archived: readonly IssueId[]; skipped: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const requested = [...new Set(input.issueIds)];
  const found = new Map(
    (await issueRepo.findIssuesByIds(input.orgId, requested)).map((issue) => [
      issue.id,
      issue,
    ]),
  );

  const archivable: Issue[] = [];
  const skipped: IssueId[] = [];
  for (const id of requested) {
    const issue = found.get(id);
    if (issue === undefined || isArchived(issue)) skipped.push(id);
    else archivable.push(issue);
  }

  for (const issue of archivable) {
    assertCan(actor, "issue:archive", issueResource(issue));
  }

  for (const issue of archivable) {
    const archived = await issueRepo.archiveIssue(input.orgId, issue.id);

    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: archived.id,
      projectId: archived.projectId,
    });
  }

  return { archived: archivable.map((issue) => issue.id), skipped };
}

